/// wire-contract documentation carry a field-level `#[allow(dead_code)]` rather
/// than a blanket suppression over the whole enum.
#[derive(Debug, Clone, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum AgentEvent {
