        effective: String,
        #[allow(dead_code)]
        reason: String,
    },
    AssistantTextDelta {
        // session_id added daemon-side so scoped SSE clients can verify the
        // frame still belongs to their active session. `default` keeps us
        // compatible with daemons that predate the field.
        #[serde(default)]
        session_id: String,
