/// Response from `GET /v1/fs/dirs?path=<path>`.
#[derive(Debug, Clone, Default, Deserialize)]
#[allow(dead_code)]
pub struct FsDirsResponse {
    #[serde(default)]
    pub ok: bool,
    #[serde(default)]
    pub path: String,
    #[serde(default)]
    pub parent: Option<String>,
    #[serde(default)]
    pub home: String,
    #[serde(default)]
    pub dirs: Vec<FsDirEntry>,
