        "{}/v1/fs/dirs?path={}&files=1",
        base_url.trim_end_matches('/'),
        encoded.as_string().unwrap_or_else(|| path.to_string())
    );
    let resp = gloo_net::http::Request::get(&url).send().await.ok()?;
    resp.json::<FsDirsResponse>().await.ok()
}

