    fn checkpoint_value(revision: u64) -> Value {
        serde_json::json!({
            "type": "projection_checkpoint",
            "persistence_revision": revision,
            "transcript": [],
            "tool_context": [],
        })
    }

    fn attach(
        store: &SessionProjectionStore,
        session_id: &str,
        revision: u64,
    ) -> SessionProjection {
        store
            .snapshot(session_id, revision, checkpoint_value(revision))
            .unwrap()
    }

    /// Contract fixture only: clients, not the daemon store, reconstruct the
    /// canonical component registry. A component call takes effect only when a
    /// later same-call-id result is explicitly successful (`is_error == false`).
    fn reconstruct_components(
        tool_context: &[ocean_core::SessionToolContext],
    ) -> BTreeMap<String, Value> {
        let mut pending = HashMap::<String, &ocean_core::SessionToolContext>::new();
        let mut components = BTreeMap::new();
        for entry in tool_context {
            match entry.kind.as_str() {
                "call"
                    if matches!(
                        entry.tool_name.as_str(),
                        "component_render" | "component_unmount"
                    ) =>
                {
                    pending.insert(entry.tool_call_id.clone(), entry);
                }
                "result" => {
                    let Some(call) = pending.remove(&entry.tool_call_id) else {
                        continue;
                    };
                    if entry.is_error != Some(false) {
                        continue;
                    }
                    let Some(arguments) = call.arguments.as_ref() else {
                        continue;
                    };
                    let Some(id) = arguments.get("id").and_then(Value::as_str) else {
                        continue;
                    };
                    if call.tool_name == "component_render" {
                        components.insert(id.to_string(), arguments.clone());
                    } else {
                        components.remove(id);
                    }
                }
                _ => {}
            }
        }
        components
    }

    fn store(lease: Duration) -> SessionProjectionStore {
        let dir = tempdir().unwrap();
        // Keep the temporary directory alive for the process-long test by using
        // a database file whose open handle remains valid after unlink on Unix.
        SessionProjectionStore::open_with_config(
            &dir.path().join("projection.db"),
            1024 * 1024,
            lease,
        )
        .unwrap()
    }

    #[cfg(unix)]
    #[test]
    fn projection_database_is_owner_only() {
        use std::os::unix::fs::PermissionsExt;
        let dir = tempdir().unwrap();
        let path = dir.path().join("projection.db");
        let _store = SessionProjectionStore::open(&path).unwrap();
        assert_eq!(
            std::fs::metadata(path).unwrap().permissions().mode() & 0o777,
            0o600
        );
    }

    #[test]
    fn cursors_are_session_scoped_contiguous_and_surface_patch_is_excluded() {
        let store = store(DEFAULT_LEASE);
        let a = AgentSessionId::new_v4();
        let b = AgentSessionId::new_v4();
        let turn = AgentTurnId::new_v4();
        let attached = attach(&store, &a.to_string(), 0);
        let first = store
            .append_agent(&AgentTurnEvent::AssistantTextDelta {
                session_id: a,
                turn_id: turn,
                delta: "a".into(),
            })
            .unwrap()
            .unwrap();
        let second = store
            .append_agent(&AgentTurnEvent::AssistantTextDelta {
                session_id: a,
                turn_id: turn,
                delta: "b".into(),
            })
            .unwrap()
            .unwrap();
        let other = store
            .append_agent(&AgentTurnEvent::AssistantTextDelta {
                session_id: b,
                turn_id: turn,
                delta: "x".into(),
            })
            .unwrap()
            .unwrap();
        assert_eq!(first.seq, 2);
        assert_eq!(second.seq, 3);
        assert_eq!(other.seq, 1);
        let excluded = store
            .append_agent(&AgentTurnEvent::SurfacePatch {
                session_id: a,
                turn_id: turn,
                canvas_id: ocean_agent_sdk::surface::CanvasId::new("main"),
                patches: vec![],
            })
            .unwrap();
        assert!(excluded.is_none());
        let page = store
            .page_after(&a.to_string(), &attached.cursor, &attached.lease_id)
            .unwrap();
        assert_eq!(page.len(), 2);
        assert!(page[1].cursor.ends_with(":3"));
    }

    #[test]
    fn folded_state_excludes_components_and_pending_frames_replay_them_once() {
        let store = store(DEFAULT_LEASE);
        let session = AgentSessionId::new_v4();
        let turn = AgentTurnId::new_v4();
        let _attached = attach(&store, &session.to_string(), 0);
        store
            .append_agent(&AgentTurnEvent::TurnStarted {
                session_id: session,
                turn_id: turn,
                model: Some("test".into()),
            })
            .unwrap();
        store
            .append_agent(&AgentTurnEvent::ComponentRender {
                session_id: session,
                component_id: "card".into(),
                kind: "markdown".into(),
                props: serde_json::json!({"text":"one"}),
                replace: false,
            })
            .unwrap();
        store
            .append_agent(&AgentTurnEvent::ComponentUnmount {
                session_id: session,
                component_id: "card".into(),
            })
            .unwrap();
        store
            .append_agent(&AgentTurnEvent::BrowserActivity {
                session_id: session,
                active: true,
            })
            .unwrap();
        let permission_id = ocean_core::PermissionId::new_v4();
        let mut request = EventEnvelope::new(OceanEvent::PermissionRequest {
            tool: "bash".into(),
            reason: "approval".into(),
            args: serde_json::json!({}),
        });
        request.session_id = Some(session.0);
        request.permission_id = Some(permission_id);
        store.append_control(&request).unwrap();
        let snapshot = attach(&store, &session.to_string(), 0);
        let state = &snapshot.state;
        assert!(state.active_turn.is_some());
        assert!(state.browser_active);
        assert_eq!(state.pending_permissions.len(), 1);
        let component_kinds = snapshot
            .pending_events
            .iter()
            .filter_map(|frame| frame.event["type"].as_str())
            .filter(|kind| matches!(*kind, "component_render" | "component_unmount"))
            .collect::<Vec<_>>();
        assert_eq!(
            component_kinds,
            vec!["component_render", "component_unmount"]
        );
        let mut decision = EventEnvelope::new(OceanEvent::PermissionDecision {
            allowed: true,
            reason: None,
        });
        decision.session_id = request.session_id;
        decision.permission_id = Some(permission_id);
        store.append_control(&decision).unwrap();
        store
            .append_agent(&AgentTurnEvent::TurnFinished {
                session_id: session,
                turn_id: turn,
                status: ocean_agent_sdk::AgentTurnStatus::Completed,
                error: None,
                wall_ms: Some(1),
                output_tokens: None,
                input_tokens: None,
                cache_read_tokens: None,
                tokens_per_second: None,
                context_usage: None,
            })
            .unwrap();
        let state = attach(&store, &session.to_string(), 0).state;
        assert!(state.active_turn.is_none());
        assert!(state.last_turn_finished.is_some());
        assert!(!state.browser_active);
        assert!(state.pending_permissions.is_empty());
    }

    #[test]
    fn concurrent_appends_allocate_one_contiguous_session_sequence() {
        let store = store(DEFAULT_LEASE);
        let session = AgentSessionId::new_v4();
        let turn = AgentTurnId::new_v4();
        let attached = attach(&store, &session.to_string(), 0);
        let mut workers = Vec::new();
        for worker in 0..4 {
            let store = store.clone();
            workers.push(std::thread::spawn(move || {
                for index in 0..25 {
                    store
                        .append_agent(&AgentTurnEvent::AssistantTextDelta {
                            session_id: session,
                            turn_id: turn,
                            delta: format!("{worker}:{index}"),
                        })
                        .unwrap();
                }
            }));
        }
        for worker in workers {
            worker.join().unwrap();
        }
        let page = store
            .page_after(&session.to_string(), &attached.cursor, &attached.lease_id)
            .unwrap();
        assert_eq!(page.len(), 100);
        let sequences = page
            .iter()
            .map(|frame| ProjectionCursor::parse(&frame.cursor).unwrap().seq)
            .collect::<Vec<_>>();
        assert_eq!(sequences, (2..=101).collect::<Vec<_>>());
    }

    #[test]
    fn cursor_validation_resets_wrong_epoch_session_future_and_malformed() {
        let store = store(DEFAULT_LEASE);
        let session = AgentSessionId::new_v4().to_string();
        let snapshot = attach(&store, &session, 0);
        assert_eq!(
            store
                .page_after(&session, "bad", &snapshot.lease_id)
                .unwrap_err(),
            ProjectionReset::Malformed
        );
        let wrong_epoch = snapshot
            .cursor
            .replacen(&*store.epoch, &Uuid::new_v4().to_string(), 1);
        assert_eq!(
            store
                .page_after(&session, &wrong_epoch, &snapshot.lease_id)
                .unwrap_err(),
            ProjectionReset::WrongEpoch
        );
        let wrong_session = AgentSessionId::new_v4().to_string();
        assert_eq!(
            store
                .page_after(&wrong_session, &snapshot.cursor, &snapshot.lease_id)
                .unwrap_err(),
            ProjectionReset::WrongSession
        );
        let future = ProjectionCursor::new(&store.epoch, &session, 2).to_string();
        assert_eq!(
            store
                .page_after(&session, &future, &snapshot.lease_id)
                .unwrap_err(),
            ProjectionReset::Future
        );
    }

