+/// Atomic session snapshot watermark and retained frames after its durable base.
+///
+/// Initial reduction precedence is normative:
+/// 1. hydrate canonical `session` from the enclosing `SessionResponse`;
+/// 2. treat this top-level aligned checkpoint as the durable base. Inline
+///    replaces normalized transcript/tool content; reconstruct components by
+///    pairing calls with later successful same-`tool_call_id` results in order.
+///    Failed, missing, or result-before-call pairs do nothing. Refetch is already
+///    satisfied by this same fresh GET;
+/// 3. reduce `pending_events` exactly once in cursor order for transcript/tool/
+///    component/checkpoint content. Inline checkpoint replaces those canonical
+///    registries; refetch aborts attach and starts a new GET;
+/// 4. install every field in `state` as an authoritative replacement, never as
+///    additional reducer events. Components are not folded state;
+/// 5. open the exclusive tail after `cursor`; tail frames reduce normally and a
+///    tail refetch checkpoint restarts this algorithm.
+#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
+pub struct SessionProjection {
+    pub version: u32,
+    pub cursor: String,
+    pub checkpoint_revision: u64,
+    /// Latest visible durable replacement. Live clients receive the same typed
+    /// payload on the checkpoint source.
+    #[serde(default, skip_serializing_if = "Option::is_none")]
+    pub checkpoint: Option<SessionProjectionCheckpoint>,
+    /// Identified bounded replay lease required by the projection tail.
+    pub lease_id: String,
+    pub lease_expires_ms: i64,
+    #[serde(default)]
+    pub pending_events: Vec<SessionProjectionFrame>,
+    #[serde(default)]
+    pub state: SessionProjectionState,
+}
